<?php $pageTitle='Contact Haven Hotel'; require 'db/connection.php'; require 'includes/functions.php'; if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$subject=trim($_POST['subject']??'');$message=trim($_POST['message']??'');if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||!$subject||!$message){$error='Please complete all fields with a valid email.';}else{$st=$pdo->prepare('INSERT INTO contact_messages(name,email,subject,message) VALUES(?,?,?,?)');$st->execute([$name,$email,$subject,$message]);$success='Thanks for reaching out. Our team will reply shortly.';}} include 'includes/header.php'; ?><div class="form-page wide"><div class="split"><div><span class="eyebrow">Get in touch</span><h1>We’d love to hear from you.</h1><p class="muted">Have a question about a room, a special request or help with your booking? Send us a note.</p><div class="hero-note"><strong>Haven Hotel</strong><br>24 Palm Avenue, New Delhi<br>Available 24/7 for guest assistance.<br>Leave us a message using the form.</div></div><div class="panel"><h2>Contact us</h2><?php if(!empty($error)): ?><div class="alert error"><?=e($error)?></div><?php endif;?><?php if(!empty($success)): ?><div class="alert success"><?=e($success)?></div><?php endif;?><form method="post"><div class="field"><label>Name</label><input name="name" required></div><div class="field"><label>Email</label><input type="email" name="email" required></div><div class="field"><label>Subject</label><input name="subject" required></div><div class="field"><label>Message</label><textarea name="message" required></textarea></div><button class="button" type="submit">Send message</button></form></div></div></div><?php include 'includes/footer.php'; ?>
